package co.edu.ucc.visitaregistro.bd;

/**
 * Pequeñas diferencias de SQL entre MySQL (producción) y HSQLDB
 * (base embebida para ejecutar el proyecto sin instalar nada).
 * Todo lo demás del SQL es común a las dos.
 */
public enum Dialecto {

    MYSQL(
        "INT NOT NULL AUTO_INCREMENT PRIMARY KEY",
        "DATETIME",
        " ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
    ),
    HSQLDB(
        "INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) PRIMARY KEY",
        "TIMESTAMP(0)",
        ""
    );

    private final String identificador;
    private final String fechaHora;
    private final String finTabla;

    Dialecto(String identificador, String fechaHora, String finTabla) {
        this.identificador = identificador;
        this.fechaHora = fechaHora;
        this.finTabla = finTabla;
    }

    /** Reemplaza las marcas {ID}, {FECHA_HORA} y {FIN_TABLA} de un CREATE TABLE. */
    public String adaptar(String sql) {
        return sql
            .replace("{ID}", identificador)
            .replace("{FECHA_HORA}", fechaHora)
            .replace("{FIN_TABLA}", finTabla);
    }

    public static Dialecto desdeUrl(String jdbcUrl) {
        return jdbcUrl.startsWith("jdbc:hsqldb:") ? HSQLDB : MYSQL;
    }
}
